path_types = defaultdict(set)
children = defaultdict(set)


def tname(v):
    if v is None:
        return 'null'
    if isinstance(v, bool):
        return 'boolean'
    if isinstance(v, int) and not isinstance(v, bool):
        return 'integer'
    if isinstance(v, float):
        return 'number'
    if isinstance(v, str):
        return 'string'
    if isinstance(v, list):
        return 'array'
    if isinstance(v, dict):
        return 'object'
    return type(v).__name__


def walk(v, path='$'):
    path_types[path].add(tname(v))
    if isinstance(v, dict):
        for k, vv in v.items():
            c = f"{path}.{k}"
            children[path].add(c)
            walk(vv, c)
    elif isinstance(v, list):
        c = f"{path}[]"
        children[path].add(c)
        for item in v:
            walk(item, c)

