    if path in seen:
        return
    seen.add(path)
    types = ', '.join(sorted(path_types[path]))
    lines.append('  '*indent + f'- {path} : {types}')
    for c in sorted(children.get(path, []), key=sort_key):
        emit(c, indent+1, seen)

emit('$')

print('\n'.join(lines))
