import json, math
from pathlib import Path

main=json.loads(Path('Questions/data_prep/round_5/0617_wed_1200.json').read_text())
copy=json.loads(Path('Questions/data_prep/round_5/0617_wed_1200 copy.json').read_text())

diffs=[]

def walk(a,b,path='$'):
    if isinstance(a,dict) and isinstance(b,dict):
        for k in sorted(set(a)|set(b)):
            if k not in a or k not in b:
                diffs.append((f'{path}.{k}','missing',type(a.get(k)).__name__,type(b.get(k)).__name__,a.get(k),b.get(k)))
            else:
                walk(a[k],b[k],f'{path}.{k}')
        return
    if isinstance(a,list) and isinstance(b,list):
        if len(a)!=len(b):
            diffs.append((path,'len',len(a),len(b),None,None))
            return
        for i,(x,y) in enumerate(zip(a,b)):
            walk(x,y,f'{path}[{i}]')
        return

    # strict representation compare
    same_repr = (type(a) is type(b) and repr(a)==repr(b))
    if not same_repr:
        # focus on numerics where == may still be true
        if isinstance(a,(int,float)) and isinstance(b,(int,float)) and (a==b):
            diffs.append((path,'numeric_repr',type(a).__name__,type(b).__name__,repr(a),repr(b)))
        elif a!=b:
            diffs.append((path,'value',type(a).__name__,type(b).__name__,repr(a)[:80],repr(b)[:80]))

walk(main,copy)
print('strict diffs',len(diffs))
for d in diffs[:20]:
    print(d)
