    uniq={v for _,v in vals}
    if len(vals)>1 and len(uniq)>1:
        amb+=1

print('total task-email-metric keys:',len(triples))
print('ambiguous keys (conflicting multiple values):',amb)
print('max duplicate entries for same key:',max(len(v) for v in triples.values()))
