import csv
from pathlib import Path

p = Path('Answers/results/reaults.tsv')
with p.open('r', encoding='utf-8') as f:
    rows = list(csv.reader(f, delimiter='\t'))

if not rows:
    raise SystemExit('Empty TSV')

header = rows[0]
data = rows[1:]

numeric_groups = {
    'IAA_ch': ['A_ch', 'D_ch', 'Z_ch', 'G_ch'],
    'IAA_rl': ['A_rl', 'D_rl', 'Z_rl', 'G_rl'],
    'IAA_cm': ['A_cm', 'D_cm', 'Z_cm', 'G_cm'],
    'IAA_ft': ['A_ft', 'D_ft', 'Z_ft', 'G_ft'],
    'IAA_at': ['A_at', 'D_at', 'Z_at', 'G_at'],
}

idx = {c: i for i, c in enumerate(header)}
for target, sources in numeric_groups.items():
    if target not in idx:
        raise SystemExit(f'Missing target column: {target}')
    for s in sources:
        if s not in idx:
            raise SystemExit(f'Missing source column: {s}')

filled = {k: 0 for k in numeric_groups}

for row in data:
    if len(row) < len(header):
        row.extend([''] * (len(header) - len(row)))

    for target, sources in numeric_groups.items():
        vals = []
        for s in sources:
            raw = row[idx[s]].strip()
            if raw == '':
                continue
            try:
                vals.append(float(raw))
            except ValueError:
                continue

        if not vals:
            row[idx[target]] = ''
            continue

        pct = (sum(vals) / (2.0 * len(vals))) * 100.0
        # Keep clean formatting: integers without decimal, else up to 2 decimals.
        if abs(pct - round(pct)) < 1e-9:
            out = str(int(round(pct)))
        else:
            out = f'{pct:.2f}'.rstrip('0').rstrip('.')
        row[idx[target]] = out
        filled[target] += 1

with p.open('w', encoding='utf-8', newline='') as f:
    w = csv.writer(f, delimiter='\t', lineterminator='\n')
    w.writerow(header)
    w.writerows(data)

print('rows:', len(data))
print('filled_counts:', filled)
